require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requireLogin();$db=Database::connect();marketplace_install($db);$pageTitle='Fulfillment Marketplace';$status=trim((string)($_GET['status']??''));$where="o.payment_status='paid'";$params=[];if($status!==''){$where.=' AND o.fulfillment_status=?';$params[]=$status;}$s=$db->prepare("SELECT o.*,b.name branch_name FROM online_orders o LEFT JOIN branches b ON b.id=o.branch_id WHERE {$where} ORDER BY CASE o.fulfillment_status WHEN 'waiting_pick' THEN 1 WHEN 'picking' THEN 2 WHEN 'packing' THEN 3 WHEN 'ready_ship' THEN 4 WHEN 'ready_pickup' THEN 4 ELSE 5 END,o.id ASC LIMIT 300");$s->execute($params);$rows=$s->fetchAll()?:[];require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Picking & Packing</h1><p>Operasional order paid dari picking barang sampai siap dikirim.</p></div></header><section class="mp-panel"><div class="mp-filter-row"><?php foreach([''=>'Semua','waiting_pick'=>'Menunggu Picking','picking'=>'Picking','packing'=>'Packing','ready_ship'=>'Siap Dikirim','ready_pickup'=>'Siap Diambil','shipped'=>'Dikirim'] as $k=>$l):?><a class="mp-btn soft <?=$status===$k?'active':''?>" href="?status=<?=urlencode($k)?>"><?=$l?></a><?php endforeach;?></div><div class="table-premium-card"><table class="premium-table js-data-table"><thead><tr><th>Order</th><th>Pelanggan</th><th>Cabang</th><th>Fulfillment</th><th>Kurir</th><th>Paid</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['order_number'])?></b><br><small><?=rupiah($r['grand_total'])?></small></td><td><?=e($r['recipient_name'])?><br><small><?=e($r['recipient_phone'])?></small></td><td><?=e($r['branch_name']?:'-')?></td><td><span class="mp-badge"><?=e(ucwords(str_replace('_',' ',$r['fulfillment_status']?:'waiting_pick')))?></span></td><td><?=e((string)$r['courier_code']==='pickup'?'Ambil di Toko':(strtoupper($r['courier_code']).' '.$r['courier_service']))?></td><td><?=!empty($r['paid_at'])?e(date('d/m H:i',strtotime($r['paid_at']))):'-'?></td><td><a class="mp-btn soft" href="<?=legacy_base_url('admin/marketplace-fulfillment/detail.php?id='.(int)$r['id'])?>"><i class="bi bi-box-seam"></i> Proses</a></td></tr><?php endforeach;?></tbody></table></div></section></main><?php require __DIR__.'/../../layouts/admin-footer.php';?>
